<style>
:root{--ba-brand-primary:#155f53;--ba-primary-text:#fff;--ba-primary-ink:#124f46;--ba-brand-secondary:#334b73;--ba-secondary-ink:#283c5b;--public-paper:#fff;--public-canvas:#f4f8f9;--public-ink:#182f39;--public-muted:#516570;--public-line:#d9e5e7;color-scheme:light;scrollbar-color:#8da9aa #f4f8f9;scrollbar-width:thin}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:30px}body{margin:0;color:var(--public-ink);background:var(--public-paper);font-family:Tahoma,"Segoe UI",Arial,sans-serif;line-height:1.9}a{color:inherit}button,a{touch-action:manipulation}button{font:inherit;cursor:pointer}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--ba-secondary-ink);outline-offset:5px}p,h1,h2,h3{margin-block-start:0}h1,h2,h3{line-height:1.5}p{color:var(--public-muted)}.public-wrap{width:min(1160px,calc(100% - 48px));margin-inline:auto}.public-skip{position:absolute;inset-block-start:-100px;background:white;padding:10px;z-index:5}.public-skip:focus{inset-block-start:10px}.public-nav{display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:100px;border-bottom:1px solid var(--public-line)}.public-brand{font-family:"Segoe UI",Arial,sans-serif;font-size:27px;font-weight:750;letter-spacing:-1.5px;text-decoration:none;color:var(--ba-primary-ink)}.public-brand span{color:var(--ba-secondary-ink)}.public-links{display:flex;flex-wrap:wrap;gap:22px;align-items:center;font-size:14px}.public-links a{text-decoration:none}.public-links a:hover{text-decoration:underline}.public-language{display:inline;margin:0}.public-language button{border:1px solid var(--public-line);border-radius:8px;background:white;padding:5px 12px;min-height:40px}.public-language button:hover{background:var(--public-canvas)}.public-hero{display:grid;grid-template-columns:1.15fr .85fr;gap:72px;padding-block:84px 78px;align-items:center}.public-eyebrow{color:var(--ba-primary-ink);font-size:14px;font-weight:700;display:block;margin-block-end:20px}.public-hero h1{font-size:clamp(34px,4.3vw,54px);letter-spacing:-.7px;margin-block-end:22px}.public-hero h1 span{color:var(--ba-primary-ink)}.public-hero .public-lead{font-size:18px;max-width:620px}.public-actions{display:flex;gap:14px;flex-wrap:wrap;margin-block:30px 18px}.public-button{display:inline-flex;align-items:center;justify-content:center;gap:12px;padding:12px 24px;min-height:50px;border-radius:9px;font-weight:700;text-decoration:none;border:1px solid var(--public-line)}.public-button.primary{background:var(--ba-brand-primary);color:var(--ba-primary-text);border-color:var(--ba-brand-primary)}.public-button:hover{box-shadow:0 3px 0 #182f391c;transform:translateY(-1px)}.public-note{font-size:13px}.public-route{background:var(--public-canvas);border-radius:24px;padding:30px;position:relative}.public-route:before{content:"";position:absolute;border-inline-start:1px solid #b7cece;inset-inline-start:48px;inset-block:80px 70px}.public-route-head{font-size:13px;color:var(--public-muted);margin-bottom:26px}.public-step{position:relative;display:grid;grid-template-columns:36px 1fr;gap:14px;padding-block:15px}.public-dot{width:36px;height:36px;border:1px solid #b7cece;border-radius:50%;display:grid;place-items:center;background:var(--public-paper);color:var(--ba-primary-ink);font-size:14px;font-family:"Segoe UI",Arial,sans-serif}.public-step strong{display:block;font-size:18px}.public-step p{font-size:14px;margin-block:4px 0}.public-step:last-of-type .public-dot{background:var(--ba-brand-primary);color:var(--ba-primary-text)}.public-section{padding-block:76px;border-top:1px solid var(--public-line)}.public-heading{max-width:700px;margin-block-end:32px}.public-heading h2{font-size:clamp(25px,3vw,34px);margin-block-end:12px}.public-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:30px}.public-feature{padding-inline-start:22px;border-inline-start:2px solid var(--public-line)}.public-feature h3{font-size:19px;margin-block-end:12px}.public-feature p{font-size:15px;margin:0}.public-state{font-size:12px;display:inline-block;border-radius:5px;padding:2px 9px;background:#edf5f1;color:#175241;margin-block-end:16px}.public-state.planned{background:#eef1f7;color:#344b70}.public-band{background:var(--public-canvas)}.public-availability{display:grid;grid-template-columns:1fr 1fr;gap:50px}.public-availability ul{padding-inline-start:22px;color:var(--public-muted)}.public-availability li{padding-block:7px}.public-faq{max-width:850px}.public-faq details{padding-block:20px;border-bottom:1px solid var(--public-line)}.public-faq summary{font-weight:700;cursor:pointer}.public-faq p{margin-block:14px 0}.public-footer{border-top:1px solid var(--public-line);padding-block:35px;font-size:14px;display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap}.public-footer p{margin:0}.public-notice{background:#fff5dd;border-bottom:1px solid #e6d5a8;padding:12px 24px;color:#59451a}.public-maintenance{min-height:75vh;display:grid;align-content:center;max-width:700px;padding-block:64px}.public-maintenance h1{font-size:38px}.public-maintenance p{font-size:18px}.public-maintenance small{color:var(--public-muted)}@media(max-width:760px){.public-wrap{width:calc(100% - 36px)}.public-nav{align-items:flex-start;flex-direction:column;gap:14px;padding-block:18px}.public-links{gap:15px;font-size:13px}.public-hero{grid-template-columns:1fr;gap:32px;padding-block:48px}.public-route{padding:24px}.public-route:before{inset-inline-start:42px}.public-grid,.public-availability{grid-template-columns:1fr;gap:28px}.public-section{padding-block:45px}.public-button{padding:10px 18px}.public-hero .public-lead{font-size:17px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.public-button:hover{transform:none}}@media(forced-colors:active){*{scrollbar-color:auto}.public-button,.public-state{border:1px solid ButtonText}}
</style>
